BEGIN;
CREATE SCHEMA IF NOT EXISTS identity;
CREATE SCHEMA IF NOT EXISTS connections;
CREATE SCHEMA IF NOT EXISTS inventory;
CREATE TABLE identity.users (user_id uuid PRIMARY KEY, username varchar(128) NOT NULL, normalized_username varchar(128) NOT NULL UNIQUE, display_name varchar(200) NOT NULL, status varchar(24) NOT NULL CHECK(status IN ('active','locked','disabled')), password_hash text NOT NULL, row_version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE identity.roles (role_id uuid PRIMARY KEY, normalized_name varchar(128) NOT NULL UNIQUE, display_name varchar(200) NOT NULL, is_system boolean NOT NULL DEFAULT false);
CREATE TABLE identity.permissions (permission_key varchar(128) PRIMARY KEY, description varchar(500) NOT NULL);
CREATE TABLE identity.user_roles (user_id uuid NOT NULL REFERENCES identity.users(user_id), role_id uuid NOT NULL REFERENCES identity.roles(role_id), granted_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,role_id));
CREATE TABLE identity.role_permissions (role_id uuid NOT NULL REFERENCES identity.roles(role_id), permission_key varchar(128) NOT NULL REFERENCES identity.permissions(permission_key), PRIMARY KEY(role_id,permission_key));
CREATE TABLE identity.sessions (session_id_hash char(64) PRIMARY KEY, user_id uuid NOT NULL REFERENCES identity.users(user_id), csrf_hash char(64) NOT NULL, created_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL, idle_expires_at timestamptz NOT NULL, absolute_expires_at timestamptz NOT NULL, revoked_at timestamptz);
CREATE INDEX ix_sessions_user_active ON identity.sessions(user_id,revoked_at);
CREATE TABLE connections.secret_references (secret_reference_id uuid PRIMARY KEY, purpose varchar(128) NOT NULL, current_version integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE connections.secret_versions (secret_reference_id uuid NOT NULL REFERENCES connections.secret_references(secret_reference_id), version integer NOT NULL, algorithm varchar(64) NOT NULL, key_id varchar(128) NOT NULL, nonce bytea NOT NULL, ciphertext bytea NOT NULL, auth_tag bytea NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), retired_at timestamptz, PRIMARY KEY(secret_reference_id,version));
CREATE TABLE connections.provider_connections (connection_id uuid PRIMARY KEY, name varchar(200) NOT NULL, provider_type varchar(32) NOT NULL, connection_type varchar(40) NOT NULL, endpoint_uri varchar(2048), secret_reference_id uuid REFERENCES connections.secret_references(secret_reference_id), configuration jsonb NOT NULL DEFAULT '{}', status varchar(24) NOT NULL, health_state varchar(32) NOT NULL, last_success_at timestamptz, last_sync_at timestamptz, row_version bigint NOT NULL DEFAULT 1, created_by uuid REFERENCES identity.users(user_id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX ux_connections_active_name ON connections.provider_connections(lower(name)) WHERE status <> 'deleted';
CREATE TABLE inventory.resources (resource_id uuid PRIMARY KEY, connection_id uuid NOT NULL REFERENCES connections.provider_connections(connection_id), resource_type varchar(48) NOT NULL, native_id varchar(1024) NOT NULL, name varchar(512) NOT NULL, lifecycle_state varchar(24) NOT NULL, health_state varchar(24) NOT NULL, observed_at timestamptz NOT NULL, first_seen_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL, missing_since timestamptz, row_version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(connection_id,resource_type,native_id));
CREATE INDEX ix_resources_inventory ON inventory.resources(resource_type,lifecycle_state,updated_at DESC);
CREATE INDEX ix_resources_connection ON inventory.resources(connection_id,resource_type,lifecycle_state);
CREATE TABLE inventory.virtual_machines (resource_id uuid PRIMARY KEY REFERENCES inventory.resources(resource_id), power_state varchar(24) NOT NULL, guest_os varchar(512), vcpu_count integer CHECK(vcpu_count>0), memory_bytes bigint CHECK(memory_bytes>=0), storage_bytes bigint CHECK(storage_bytes>=0), private_ips inet[], public_ips inet[], region varchar(128), availability_zone varchar(128), provider_shape varchar(128));
CREATE TABLE inventory.provider_metadata (resource_id uuid PRIMARY KEY REFERENCES inventory.resources(resource_id), schema_version integer NOT NULL, payload jsonb NOT NULL, payload_hash char(64) NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
COMMIT;
